sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    // Captura o valor da carga atual no formulário
    var cargaAtual = g_form.getValue('carga_pedido');

    // Faz a chamada ao Script Include via GlideAjax
    var ga = new GlideAjax('x_2066889_centra_0.IncidenteLogisticoUtils');
    ga.addParam('sysparm_name', 'verificarDuplicidade');
    ga.addParam('sysparm_rota', newValue); 
    ga.addParam('sysparm_carga', cargaAtual);

    ga.getXMLAnswer(function(answer) {
        // Se o servidor encontrar duplicidade, exibe o aviso amarelo no campo
        if (answer === 'true') {
            g_form.showFieldMsg('rota', 'Atenção: Já existe um incidente ativo registrado para esta Rota.', 'warning');
        } else {
            // Se não houver duplicidade, remove o aviso caso estivesse visível
            g_form.hideFieldMsg('rota');
        }
    });
}
